const { chromium } = require('/opt/browser-node/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  await page.goto('http://127.0.0.1:4001/?mode=filter', { waitUntil: 'networkidle' });
  if (await page.locator('.bookmark-row:visible').count() !== 3) throw new Error('expanded collection missing');
