  if (!(await page.getByRole('heading', { name: 'An Architecture Lover’s Guide to Rome' }).isVisible())) throw new Error('second travel result missing');
  if (await page.getByRole('heading', { name: 'Pasta alla Gricia' }).isVisible()) throw new Error('unrelated result remained');
  if ((await page.locator('.collection-count').innerText()) !== '2 bookmarks') throw new Error('visible count wrong');
  await page.getByRole('button', { name: 'Show all bookmarks' }).click();
  if (await page.locator('.bookmark-row:visible').count() !== 3) throw new Error('clear filter failed');
  console.log('Tag filtering flow passed');
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
